def main():
    for stem,d in DATA.items():
        (LESSONS/f"{stem}.md").write_text(render(stem,d),encoding="utf-8")
        marker,body=SVGS[stem]
        renderer = legacy_svg if stem == "33-geometry-language" else svg
        (MAPS/f"map-{stem[:2]}-{stem[3:]}.svg").write_text(renderer(d['title'],d['alt'],marker,body),encoding="utf-8")
        print(stem)


if __name__ == "__main__": main()
